package com.adeel.whatshelper;

import android.app.*;import android.os.*;import android.provider.Settings;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.widget.*;import java.io.*;import java.net.*;import org.json.*;

public class MainActivity extends Activity{
 LinearLayout root; EditText input,output; android.content.SharedPreferences prefs;
 int green=Color.rgb(37,211,102), white=Color.rgb(240,255,247), muted=Color.rgb(160,185,175);
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("cfg",0); build(); ingest(getIntent());}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i); ingest(i);}
 TextView tv(String s,int sp){TextView v=new TextView(this);v.setText(s);v.setTextColor(white);v.setTextSize(sp);return v;}
 Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(12);b.setAllCaps(false);GradientDrawable g=new GradientDrawable();g.setColor(Color.rgb(24,52,42));g.setCornerRadius(40);g.setStroke(1,Color.rgb(50,120,90));b.setBackground(g);return b;}
 void build(){ScrollView sv=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,40,24,30);root.setBackgroundResource(com.adeel.whatshelper.R.drawable.bg);sv.addView(root);setContentView(sv);
  TextView h=tv("WhatsHelper AI",28);h.setTypeface(null,1);root.addView(h); TextView sub=tv("Your AI copilot for WhatsApp chats",14);sub.setTextColor(muted);root.addView(sub);space(18);
  input=new EditText(this);input.setHint("Paste a message or share text here from WhatsApp…");input.setHintTextColor(muted);input.setTextColor(white);input.setMinLines(5);input.setGravity(Gravity.TOP);input.setPadding(18,18,18,18);input.setBackgroundResource(R.drawable.card);root.addView(input,new LinearLayout.LayoutParams(-1,-2));space(14);
  String[] acts={"Smart Reply","Rewrite","Professional","Friendly","Shorten","Explain","Summarize","Translate → English","Translate → Urdu","Roman Urdu"};LinearLayout grid=new LinearLayout(this);grid.setOrientation(LinearLayout.VERTICAL);for(int i=0;i<acts.length;i+=2){LinearLayout row=new LinearLayout(this);for(int j=i;j<Math.min(i+2,acts.length);j++){Button x=btn(acts[j]);String a=acts[j];x.setOnClickListener(v->runAI(a));row.addView(x,new LinearLayout.LayoutParams(0,56,1));}grid.addView(row);}root.addView(grid);space(14);
  output=new EditText(this);output.setHint("AI result appears here…");output.setHintTextColor(muted);output.setTextColor(white);output.setMinLines(5);output.setGravity(Gravity.TOP);output.setPadding(18,18,18,18);output.setBackgroundResource(R.drawable.card);root.addView(output);space(10);
  LinearLayout actions=new LinearLayout(this);Button copy=btn("Copy result");copy.setOnClickListener(v->copy());Button wa=btn("Open WhatsApp");wa.setOnClickListener(v->openWA());actions.addView(copy,new LinearLayout.LayoutParams(0,56,1));actions.addView(wa,new LinearLayout.LayoutParams(0,56,1));root.addView(actions);
  Button bubble=btn("Enable floating helper bubble");bubble.setOnClickListener(v->toggleBubble());root.addView(bubble,new LinearLayout.LayoutParams(-1,60));Button settings=btn("AI Settings");settings.setOnClickListener(v->settings());root.addView(settings,new LinearLayout.LayoutParams(-1,60));
  TextView foot=tv("Tip: In WhatsApp, select/share text → WhatsHelper AI. Your API key is stored only in this app's local preferences.",12);foot.setTextColor(muted);root.addView(foot);
 }
 void space(int n){Space s=new Space(this);root.addView(s,new LinearLayout.LayoutParams(1,n));}
 void ingest(Intent i){if(i==null)return;CharSequence t=i.getCharSequenceExtra(Intent.EXTRA_TEXT);if(t==null)t=i.getCharSequenceExtra(Intent.EXTRA_PROCESS_TEXT);if(t!=null&&input!=null)input.setText(t);}
 void runAI(String action){String text=input.getText().toString().trim();if(text.isEmpty()){toast("Add a message first");return;}String key=prefs.getString("key","");if(key.isEmpty()){settings();toast("Add an AI API key first");return;}output.setText("Thinking…");new Thread(()->{try{String r=callAI(action,text);runOnUiThread(()->output.setText(r));}catch(Exception e){runOnUiThread(()->output.setText("AI request failed: "+e.getMessage()));}}).start();}
 String instruction(String a){switch(a){case "Smart Reply":return "Write the best natural reply to this WhatsApp message. Return only the reply.";case "Rewrite":return "Rewrite this message clearly and naturally, preserving meaning. Return only rewritten text.";case "Professional":return "Rewrite as a concise professional WhatsApp message.";case "Friendly":return "Rewrite as a warm friendly natural WhatsApp message.";case "Shorten":return "Make this message much shorter without losing important meaning.";case "Explain":return "Explain what this message means, including tone or implied meaning if reasonably inferable.";case "Summarize":return "Summarize the message into concise key points.";case "Translate → English":return "Translate accurately to natural English. Return only translation.";case "Translate → Urdu":return "Translate accurately to natural Urdu script. Return only translation.";default:return "Convert this into natural Pakistani Roman Urdu. Return only converted text.";}}
 String callAI(String action,String text)throws Exception{String endpoint=prefs.getString("endpoint","https://api.openai.com/v1/chat/completions");String model=prefs.getString("model","gpt-4.1-mini");URL u=new URL(endpoint);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestMethod("POST");c.setRequestProperty("Authorization","Bearer "+prefs.getString("key",""));c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);c.setConnectTimeout(20000);c.setReadTimeout(60000);JSONObject body=new JSONObject();body.put("model",model);JSONArray msgs=new JSONArray();msgs.put(new JSONObject().put("role","system").put("content","You are a WhatsApp writing assistant. Be accurate, natural and concise. "+instruction(action)));msgs.put(new JSONObject().put("role","user").put("content",text));body.put("messages",msgs);try(OutputStream os=c.getOutputStream()){os.write(body.toString().getBytes("UTF-8"));}InputStream is=(c.getResponseCode()<400)?c.getInputStream():c.getErrorStream();String raw=new String(is.readAllBytes(),"UTF-8");if(c.getResponseCode()>=400)throw new Exception(raw.length()>180?raw.substring(0,180):raw);return new JSONObject(raw).getJSONArray("choices").getJSONObject(0).getJSONObject("message").getString("content").trim();}
 void copy(){String t=output.getText().toString();if(t.isEmpty())return;((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("WhatsHelper",t));toast("Copied");}
 void openWA(){try{Intent i=getPackageManager().getLaunchIntentForPackage("com.whatsapp");if(i==null)i=getPackageManager().getLaunchIntentForPackage("com.whatsapp.w4b");if(i!=null)startActivity(i);else toast("WhatsApp not found");}catch(Exception e){toast("Could not open WhatsApp");}}
 void toggleBubble(){if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION, Uri.parse("package:"+getPackageName())));toast("Allow display over other apps, then tap again");return;}startService(new Intent(this,OverlayService.class));toast("Floating helper enabled");}
 void settings(){LinearLayout l=new LinearLayout(this);l.setPadding(30,10,30,0);l.setOrientation(LinearLayout.VERTICAL);EditText ep=new EditText(this);ep.setHint("OpenAI-compatible endpoint");ep.setText(prefs.getString("endpoint","https://api.openai.com/v1/chat/completions"));EditText mo=new EditText(this);mo.setHint("Model");mo.setText(prefs.getString("model","gpt-4.1-mini"));EditText k=new EditText(this);k.setHint("API key");k.setInputType(129);k.setText(prefs.getString("key",""));l.addView(ep);l.addView(mo);l.addView(k);new AlertDialog.Builder(this).setTitle("AI connection").setMessage("Works with OpenAI-compatible chat-completions APIs.").setView(l).setPositiveButton("Save",(d,w)->prefs.edit().putString("endpoint",ep.getText().toString().trim()).putString("model",mo.getText().toString().trim()).putString("key",k.getText().toString().trim()).apply()).setNegativeButton("Cancel",null).show();}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
}
